function parseExistingNames() {
  return new Set(fs.readFileSync(existingPath, 'utf8')
    .split(/\r?\n/)
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line).condition_name.trim().toLocaleLowerCase()));
}

function referenceFor(sourceKey) {
  const source = SOURCES[sourceKey];
  if (!source) throw new Error(`Unknown source key: ${sourceKey}`);
  return {
    citation: `${source.citation} ${source.url}`,
    key_finding: source.finding,
    study_type: source.type,
    url: source.url,
    catalogue_verified_at: REVIEW_DATE,
    verification: 'catalogue_source_linked',
  };
}

function recordFor(spec) {
  const outcomeMeasures = [...spec.outcomes];
  if (outcomeMeasures.length < 3) outcomeMeasures.push('Goal Attainment Scaling');
  const exercises = spec.interventions.map(([name, dosage, purpose, modifications = 'Tailor load, range, support and environment to assessment findings and response.']) => ({
    name,
    type: name.toLocaleLowerCase().includes('education') || name.toLocaleLowerCase().includes('plan') ? 'Education and self-management' : 'Active rehabilitation',
    dosage,
    purpose,
    modifications,
    evidence_level: 'Source-linked guideline component; individual prescription required',
  }));
  return {
    condition_name: spec.name,
    category: spec.category,
    overview: {
      pathophysiology: spec.summary,
      functional_impact: spec.impact,
      prevalence: 'Presentation frequency and prognosis vary by population, setting and case definition; use current local epidemiology when prevalence is material.',
    },
    assessment: {
      key_assessments: spec.assessments,
      outcome_measures: outcomeMeasures,
      screening_tools: spec.screening,
      evidence_base: 'Complete a person-specific baseline, differential and red-flag screen; repeat the same validated measures at meaningful review points.',
    },
    exercise_prescription: {
      exercises,
      frequency: 'Combine clinician-supervised review with an individual home or community programme; frequency is specified per component and adjusted to recovery response.',
      session_duration: 'Use tolerable, goal-directed sessions; distribute practice when fatigue, pain, respiratory load or motor-learning needs favour shorter bouts.',
      program_duration: spec.timeframe || 'Begin with a 6-12 week review horizon, then continue, progress or discharge according to objective change and participation goals.',
      evidence_summary: 'Active rehabilitation is the base intervention. Select only components supported by the individual assessment, relevant source guidance, preferences and response.',
    },
    progression: {
      phases: [
        { phase_name: 'Baseline and safety', duration: 'Initial assessment and early sessions', goals: 'Confirm presentation, establish measures and identify constraints.', criteria: 'Red flags addressed; starting load and meaningful goals agreed.' },
        { phase_name: 'Capacity development', duration: 'Individualised', goals: 'Progress the selected active components and self-management.', criteria: 'Acceptable symptom response, recovery and measurable functional gain.' },
        { phase_name: 'Participation and discharge', duration: 'Criteria-based', goals: 'Transfer gains to work, home, community or sport and establish an independent plan.', criteria: 'Goals met or a clear long-term pathway, escalation or referral is documented.' },
      ],
      evidence_base: 'Progress by objective capacity, symptom recovery, movement quality and participation criteria rather than elapsed time alone.',
    },
    contraindications: {
      absolute: ['Medical instability or an emergency presentation requiring assessment before rehabilitation.', 'A procedure-specific restriction that prohibits the proposed activity.'],
      relative: ['High irritability, severe fatigue, unstable comorbidity or poor recovery requiring reduced dose or closer monitoring.', 'Insufficient diagnostic clarity for the proposed high-load or high-risk activity.'],
      red_flags: spec.redFlags,
    },
    outcomes: {
      expected_timeframe: spec.timeframe || 'Review early response within 2-4 weeks and objective function within 6-12 weeks; use condition-specific milestones where supplied.',
      key_outcomes: [...outcomeMeasures, 'Achievement of the person’s agreed participation goal'],
      success_indicators: ['Objective improvement on at least one repeated measure', 'Greater task or participation tolerance', 'An independent self-management or maintenance pathway'],
      effect_sizes: 'No universal pooled effect is asserted. Record individual baseline, follow-up value and measurement interval.',
    },
    meta_analysis_summary: {
      key_findings: ['Use active, goal-directed rehabilitation as the core pathway.', 'Match intervention selection and dose to findings and response.', 'Escalate atypical, deteriorating or non-responsive presentations.'],
      pooled_effects: 'Not imported because effect estimates differ by population, intervention and outcome; consult the linked source and current condition-specific evidence for quantitative estimates.',
      quality_of_evidence: 'Source-linked to current guideline or consensus material; evidence certainty varies by component and condition.',
    },
    references: spec.sources.map(referenceFor),
    clinical_note: 'This is a source-linked starting pathway, not an automatic prescription. Confirm diagnosis or working presentation, contraindications, preferences, service scope and response before applying or progressing any component.',
    last_updated: REVIEW_DATE,
    evidence_status: 'source_linked',
    evidence_reviewed_at: REVIEW_DATE,
    source_revision: 'assesssuite-shared-protocol-library-r3.1',
    applicable_professions: ['physiotherapy', 'exercise-physiology'],
  };
}

const existingNames = parseExistingNames();
const names = new Set();
const records = specs.map((spec) => {
  const key = spec.name.trim().toLocaleLowerCase();
  if (!key) throw new Error('A protocol is missing its condition name');
  if (existingNames.has(key)) throw new Error(`Protocol duplicates part 0: ${spec.name}`);
  if (names.has(key)) throw new Error(`Duplicate generated protocol: ${spec.name}`);
  names.add(key);
  if (!Array.isArray(spec.interventions) || spec.interventions.length < 4) {
    throw new Error(`Protocol needs at least four active components: ${spec.name}`);
  }
  if (!Array.isArray(spec.sources) || spec.sources.length === 0) {
    throw new Error(`Protocol needs at least one source: ${spec.name}`);
  }
  return recordFor(spec);
});

const output = `${records.map((record) => JSON.stringify(record)).join('\n')}\n`;
if (process.argv.includes('--check')) {
  if (!fs.existsSync(outputPath) || fs.readFileSync(outputPath, 'utf8') !== output) {
    throw new Error('Treatment protocol catalogue is not regenerated; run this script without --check.');
  }
} else {
  fs.writeFileSync(outputPath, output, 'utf8');
}

console.log(JSON.stringify({ output: outputPath, generated: records.length, sources: Object.keys(SOURCES).length }));
